#include "common.h"
static int username_exists(const char *u){FILE*f=fopen(USER_FILE,"r");char name[48],pass[128];int found=0;if(!f)return 0;while(fscanf(f,"%47[^|]|%127[^\n]\n",name,pass)==2)if(!strcmp(name,u)){found=1;break;}fclose(f);return found;}
int signup_user(void){char u[48],p[128];int attempts=0;for(;;){read_line("Choose username: ",u,sizeof u);if(!u[0]||strchr(u,'|')||strchr(u,' ')){puts("Username must be non-empty and contain no spaces or '|'.");continue;}if(username_exists(u)){puts("Username already exists. Choose another.");continue;}break;}while(attempts<5){read_line("Password (8+ chars, uppercase, lowercase, number, special): ",p,sizeof p);if(valid_password(p)){FILE*f=fopen(USER_FILE,"a");if(!f){perror("Cannot open user file");return 0;}fprintf(f,"%s|%s\n",u,p);fclose(f);puts("Sign-up successful. You can now sign in.");return 1;}attempts++;printf("Password does not meet all rules (%d/5).\n",attempts);}puts("TIME OUT. Please sign up again.");return 0;}
int signin_user(char *username){char u[48],p[128],fu[48],fp[128];int attempt;for(attempt=0;attempt<3;attempt++){read_line("Username: ",u,sizeof u);read_line("Password: ",p,sizeof p);FILE*f=fopen(USER_FILE,"r");int ok=0;if(f){while(fscanf(f,"%47[^|]|%127[^\n]\n",fu,fp)==2)if(!strcmp(u,fu)&&!strcmp(p,fp)){ok=1;break;}fclose(f);}if(ok){strcpy(username,u);printf("Welcome, %s!\n",u);return 1;}printf("Invalid login (%d/3).\n",attempt+1);}puts("You have reached max number of attempts. Please wait 5 minutes to login again.");return 0;}
